# Qué catálogos le sirven a cada rubro de empresa. Un sanatorio necesita los
# cinco; un laboratorio solo el suyo.
CATALOGOS_POR_VERTICAL: dict[str, tuple[str, ...]] = {
    "medical": ("consultas", "laboratorio", "imagenes"),
    "hospital": ("consultas", "laboratorio", "imagenes", "sanatorio"),
    "dental": ("odontologia",),
    "veterinary": ("veterinaria",),
    "laboratory": ("laboratorio",),
    "imaging": ("imagenes",),
}


def para_vertical(vertical: str) -> list[dict]:
    """Todos los ítems que le corresponden a un rubro, sin repetir nombres."""
    vistos: set[str] = set()
    salida: list[dict] = []
    for clave in CATALOGOS_POR_VERTICAL.get(vertical, ()):
        for item in CATALOGOS.get(clave, []):
            if item["name"] not in vistos:
                vistos.add(item["name"])
                salida.append(item)
    return salida
